import{expect,test}from"bun:test";
import Ajv from"ajv";
import{Database}from"bun:sqlite";
import laws from"../../🧫️fixtures/🪶️sqlite/🔣️.json";
import snapshot from"../../../../🧫️fixtures/🧬️mutations/👥️stakeholder/🌱️create/🌱️creates-a/📸️snapshot/➡️after/🔣️.json";
import schema from"../../🔣️.json";
import ioSchema from"../../../../../../../../../../../../../🧰️framework/🔨️modules/🚪️io/🧬️schema/🔣️.json";
import childSchema from"../../../../../../../../../../../../../🧰️framework/🛍️products/💻️os/🔨️modules/🏪️store/🪆️child/🧬️schema/🔣️.json";
import * as owner from"../../🟦️.ts";
import * as artifact from"../../../🟦️.ts";
import * as jsonBoundary from"../../../../🚪️io/📥️import/🧩️deserializers/🗿️artifacts/🔣️json/🔖️rfc8259/✳️any/🟦️.ts";
import {programArtifactFromJson,programArtifactToJson} from"../../../🔣️json/🟦️.ts";
import {exportSqliteDatabase,importSqliteDatabase} from"../../../../../../../../../../../../../🧰️framework/🔨️modules/🚪️io/🪶️sqlite-snapshot/🟦️.ts";
const independentSchema = new Ajv({strict:false,validateFormats:false}).addSchema([ioSchema,childSchema]).compile(schema);
test("Architect declared JSON boundary exposes exact typed reconstruction",()=>{expect(Object.hasOwn(jsonBoundary,"deserializeProgramJson")).toBe(true)});
test("Architect declared JSON schema independently admits exact IEEE and unsigned64 transport",async()=>{const[path]=laws.unsigned32Fixtures.BenchmarkRecord;const input=await Bun.file(new URL("../../../../"+path,import.meta.url)).json();const expected=programArtifactFromJson(input);for(const raw of laws.binary64Words){expected.benchmarksPayload[0]!.value={bits:BigInt("0x"+raw)};const wire=JSON.parse(JSON.stringify(programArtifactToJson(expected)));expect(independentSchema(wire)).toBe(true);expect(programArtifactFromJson(wire)).toEqual(expected);expect(wire.benchmarksPayload[0].value).toEqual({bits:raw})}for(const[entity,field]of laws.unsigned64Fields){const[path,slot]=(laws.unsigned64Fixtures as Record<string,string[]>)[entity]!;const input=await Bun.file(new URL("../../../../"+path,import.meta.url)).json();const expected=programArtifactFromJson(input);for(const raw of laws.unsigned64Corpus.valid){(expected as unknown as Record<string,Record<string,unknown>[]>)[slot!]![0]![field!]=BigInt(raw);const wire=JSON.parse(JSON.stringify(programArtifactToJson(expected)));expect(independentSchema(wire)).toBe(true);expect(programArtifactFromJson(wire)).toEqual(expected);expect(wire[slot!][0][field!]).toBe(raw)}}});
test("Architect required native survey count refuses JSON null independently",async()=>{const[path,slot]=laws.unsigned32Fixtures.Survey;const source=await Bun.file(new URL("../../../../"+path,import.meta.url)).json();expect(()=>artifact.parseSurvey({...source[slot!]![0],responseCount:null})).toThrow();});
test("Architect canonical native header owns every empty collection and one absent optional state",async()=>{const[path,slot]=laws.unsigned32Fixtures.BenchmarkRecord;const input=await Bun.file(new URL("../../../../"+path,import.meta.url)).json();const expected={...input[slot!]![0],value:{bits:0n},tags:[],notes:[]};expect(artifact.parseBenchmarkRecord(expected)).toEqual(expected);const omittedTags={...expected} as Record<string,unknown>;delete omittedTags.tags;expect(()=>artifact.parseBenchmarkRecord(omittedTags)).toThrow();const omittedNotes={...expected} as Record<string,unknown>;delete omittedNotes.notes;expect(()=>artifact.parseBenchmarkRecord(omittedNotes)).toThrow();expect(()=>artifact.parseBenchmarkRecord({...expected,description:null})).toThrow();expect(()=>artifact.parseBenchmarkRecord({...expected,timestamps:{...expected.timestamps,createdBy:null}})).toThrow();});
test("Architect canonical binary64 body admission preserves independently interpreted exact words",async()=>{
 const[path,slot]=laws.unsigned32Fixtures.BenchmarkRecord;const source=await Bun.file(new URL("../../../../"+path,import.meta.url)).json() as Record<string,Record<string,unknown>[]>;const original=(programArtifactFromJson(source) as unknown as Record<string,Record<string,unknown>[]>)[slot!]![0]!;
 const db=new Database(":memory:");try{db.exec("CREATE TABLE exact_word(bits INTEGER PRIMARY KEY, class TEXT NOT NULL)");for(const raw of laws.binary64Words){const bits=BigInt("0x"+raw),buffer=new ArrayBuffer(8),view=new DataView(buffer);view.setBigUint64(0,bits);const number=view.getFloat64(0),className=Number.isNaN(number)?"nan":number===Infinity?"positiveInfinity":number===-Infinity?"negativeInfinity":"finite";db.run("INSERT INTO exact_word VALUES(?,?)",[BigInt.asIntN(64,bits),className]);expect(artifact.parseBenchmarkRecord({...original,value:{bits}}) as unknown).toEqual({...original,value:{bits}});expect(db.query("SELECT printf('%016llx',bits) AS word,class FROM exact_word WHERE bits=?").get(BigInt.asIntN(64,bits))).toEqual({word:raw,class:className});}for(const value of[0,-0,NaN,Infinity,-Infinity,{bits:-1n},{bits:18446744073709551616n},{bits:0n,extra:true}])expect(()=>artifact.parseBenchmarkRecord({...original,value})).toThrow();}finally{db.close();}
});
test("Architect canonical full-width unsigned64 entity admission retains exact words and refuses coercion",async()=>{const parsers:Record<string,(value:unknown)=>unknown>={AnalysisRecord:artifact.parseAnalysisRecord,SearchFilter:artifact.parseSearchFilter,TemplateRecord:artifact.parseTemplateRecord,KnowledgeRecord:artifact.parseKnowledgeRecord};const fixtures=laws.unsigned64Fixtures as Record<string,string[]>;for(const[entity,field]of laws.unsigned64Fields){const[path,slot]=fixtures[entity]!;const source=await Bun.file(new URL("../../../../"+path,import.meta.url)).json() as Record<string,Record<string,unknown>[]>;const original=(programArtifactFromJson(source) as unknown as Record<string,Record<string,unknown>[]>)[slot!]![0]!;for(const raw of laws.unsigned64Corpus.valid){const word=BigInt(raw);expect(word.toString()).toBe(raw);const expected={...original,[field!]:word};expect(parsers[entity]!(expected)).toEqual(expected)}for(const value of [...laws.unsigned64Corpus.invalid.map(BigInt),0,1,0.5,"0",true,NaN,Infinity])expect(()=>parsers[entity]!({...original,[field!]:value})).toThrow()}});
test("Architect independent schema admits the persisted parent fixture",()=>{expect(independentSchema(snapshot)).toBe(true);const expected=programArtifactFromJson(snapshot);expect(owner.parseProgramSnapshot(expected) as unknown).toEqual(expected)});
test("Architect independent schema admits literal independent child identities",()=>{const input=structuredClone(snapshot);input.knowledge.childId="local 世界\0";input.knowledge.target.artifactId="foreign !@";input.benchmarks.childId="";input.benchmarks.target.artifactId="same";expect(independentSchema(input)).toBe(true);const expected=programArtifactFromJson(input);expect(owner.parseProgramSnapshot(expected) as unknown).toEqual(expected)});
test("Architect neutral identity corpus is independently parsed without normalizing literal domains",()=>{expect(JSON.parse(JSON.stringify(laws.idTexts))).toEqual(laws.idTexts);expect(laws.control.largeCharacters).toBeGreaterThan(65536)});
test("Architect public persisted facade exposes both complete semantic directions",()=>{expect(Object.hasOwn(owner,"programSnapshotToSqliteDatabase")).toBe(true);expect(Object.hasOwn(owner,"programSnapshotFromSqliteDatabase")).toBe(true)});
async function completeFixture(){const input=structuredClone(snapshot) as Record<string,unknown>;for(const[key,folder,caseName]of laws.registerFixtures){const source=await Bun.file(new URL("../../../../🧫️fixtures/🧬️mutations/"+folder+"/"+caseName+"/📸️snapshot/➡️after/🔣️.json",import.meta.url)).json();expect(source[key!]).toHaveLength(1);input[key!]=source[key!]}return programArtifactFromJson(input)}
test("Architect complete sixty-five typed bodies round-trip through independently queryable SQLite",async()=>{const expected=await completeFixture();const actual=await owner.programSnapshotToSqliteDatabase(expected);expect(actual.tables).toHaveLength(685);const physical=await exportSqliteDatabase(actual);const db=Database.deserialize(physical);try{expect(db.query("PRAGMA integrity_check").get()).toEqual({integrity_check:"ok"});expect(db.query("PRAGMA foreign_key_check").all()).toEqual([]);for(const[register,table]of Object.entries(laws.registerTables)){const headers=db.query("SELECT id,ordinal FROM architect_entity_header WHERE register=?").all(register) as{id:number;ordinal:number}[];expect(headers).toHaveLength(1);expect(headers[0]!.ordinal).toBe(0);expect(db.query("SELECT id FROM "+table).all()).toEqual([{id:headers[0]!.id}])}const imported=await importSqliteDatabase(db.serialize());const restored=await owner.programSnapshotFromSqliteDatabase(imported);expect(restored).toEqual(expected)}finally{db.close()}});

test("Architect authored global and shared header entities declare independently queryable columns",async()=>{const file=Bun.file(new URL("../../🪶️sqlite/🗄️.sql",import.meta.url));expect(await file.exists()).toBe(true);const db=new Database(":memory:");try{db.run(await file.text());for(const[table,count]of Object.entries(laws.coreColumns))expect(db.query('PRAGMA table_info("'+table+'")').all().length).toBe(count);expect(db.query("SELECT name FROM sqlite_schema WHERE type='index'").all()).toEqual([]);expect(db.query("PRAGMA foreign_key_check").all()).toEqual([])}finally{db.close()}});

test("Architect every persisted register has its own authored semantic body entity",async()=>{const db=new Database(":memory:");try{db.run(await Bun.file(new URL("../../🪶️sqlite/🗄️.sql",import.meta.url)).text());const names=new Set(db.query("SELECT name FROM sqlite_schema WHERE type='table'").all().map(row=>(row as{name:string}).name));expect(Object.keys(laws.registerTables)).toHaveLength(65);for(const table of Object.values(laws.registerTables))expect(names.has(table)).toBe(true)}finally{db.close()}});

test("Architect complete first register bodies and raw quantity words are independently queryable",async()=>{const db=new Database(":memory:");try{db.run(await Bun.file(new URL("../../🪶️sqlite/🗄️.sql",import.meta.url)).text());for(const[table,columns]of Object.entries(laws.firstBodyColumns))expect(db.query('PRAGMA table_info("'+table+'")').all().map(row=>(row as{name:string}).name)).toEqual(columns);for(const table of["architect_activity_participants","architect_function_staffing","architect_element_area","architect_element_volume","architect_element_height","architect_element_occupancy"])expect(db.query('PRAGMA foreign_key_list("'+table+'")').all().length).toBe(2);expect(db.query("PRAGMA foreign_key_check").all()).toEqual([])}finally{db.close()}});

test("Architect authored integer schema matches all eight native unsigned32 domains",()=>{const defs=schema.$defs as unknown as Record<string,{properties:Record<string,object>}>;for(const[entity,field]of laws.unsigned32Fields){const accepts=new Ajv({strict:false}).compile(defs[entity]!.properties[field]!);for(const value of laws.unsigned32Corpus.valid)expect(accepts(value)).toBe(true);for(const value of laws.unsigned32Corpus.invalid)expect(accepts(value)).toBe(false)}});

test("Architect typed integer admission agrees with independent schema at every unsigned32 frontier",async()=>{const parsers:Record<string,(value:unknown)=>unknown>={Equipment:artifact.parseEquipment,ScheduleRequirement:artifact.parseScheduleRequirement,GrowthPlan:artifact.parseGrowthPlan,PriorityRecord:artifact.parsePriorityRecord,Survey:artifact.parseSurvey,BenchmarkRecord:artifact.parseBenchmarkRecord};const fixtures=laws.unsigned32Fixtures as Record<string,string[]>;for(const[entity,field]of laws.unsigned32Fields){const[path,slot]=fixtures[entity]!;const source=await Bun.file(new URL("../../../../"+path,import.meta.url)).json() as Record<string,Record<string,unknown>[]>;const original=(programArtifactFromJson(source) as unknown as Record<string,Record<string,unknown>[]>)[slot!]![0]!;for(const value of laws.unsigned32Corpus.valid){const expected={...original,[field!]:value};expect(parsers[entity]!(expected)).toEqual(expected)}for(const value of laws.unsigned32Corpus.invalid)expect(()=>parsers[entity]!({...original,[field!]:value})).toThrow()}});


let oracleFixture:Promise<{expected:artifact.ProgramArtifact;database:Awaited<ReturnType<typeof owner.programSnapshotToSqliteDatabase>>;bytes:Uint8Array}>|undefined;
function completeOracleFixture(){return oracleFixture??=(async()=>{const expected=await completeFixture(),database=await owner.programSnapshotToSqliteDatabase(expected),bytes=await exportSqliteDatabase(database);return{expected,database,bytes}})()}
for(const sql of laws.malformedSql)test("Architect malformed independent SQL refuses: "+sql,async()=>{const{bytes}=await completeOracleFixture(),db=Database.deserialize(bytes);try{db.exec("PRAGMA ignore_check_constraints=ON");db.exec(sql);await expect(owner.programSnapshotFromSqliteDatabase(await importSqliteDatabase(db.serialize()))).rejects.toThrow()}finally{db.close()}});
for(const raw of laws.binary64Words)test("Architect independent SQL preserves exact IEEE word "+raw,async()=>{const{bytes}=await completeOracleFixture(),db=Database.deserialize(bytes);try{const bits=BigInt("0x"+raw),view=new DataView(new ArrayBuffer(8));view.setBigUint64(0,bits);const value=view.getFloat64(0),kind=Number.isNaN(value)?"nan":value===Infinity?"positiveInfinity":value===-Infinity?"negativeInfinity":"finite";db.run("UPDATE architect_benchmark_record SET value=?,value_ieee754_bits=?,value_ieee754_class=?",[Number.isNaN(value)?null:value,BigInt.asIntN(64,bits),kind]);const restored=await owner.programSnapshotFromSqliteDatabase(await importSqliteDatabase(db.serialize()));expect(restored.benchmarksPayload[0]!.value.bits).toBe(bits);const rewritten=Database.deserialize(await exportSqliteDatabase(await owner.programSnapshotToSqliteDatabase(restored)));try{expect(rewritten.query("SELECT printf('%016llx',value_ieee754_bits) AS word,value_ieee754_class AS kind FROM architect_benchmark_record").get()).toEqual({word:raw,kind});expect((await owner.programSnapshotFromSqliteDatabase(await importSqliteDatabase(rewritten.serialize()))).benchmarksPayload[0]!.value.bits).toBe(bits)}finally{rewritten.close()}}finally{db.close()}});

test("Architect consistent structural surrogate renumbering retains logical state",async()=>{const{expected,database}=await completeOracleFixture();const tables=database.tables.map(table=>({...table,rows:table.rows.map(row=>({rowid:row.rowid,values:[...row.values]}))}));const header=tables.find(table=>table.name==="architect_entity_header")!.rows.find(row=>row.values[2]==="stakeholders")!,old=header.rowid,next=900000n;header.rowid=next;header.values[0]=next;tables.find(table=>table.name==="architect_stakeholder")!.rows.find(row=>row.rowid===old)!.rowid=next;tables.find(table=>table.name==="architect_stakeholder")!.rows.find(row=>row.rowid===next)!.values[0]=next;for(const table of tables.filter(table=>table.name==="architect_entity_consultant"||table.name==="architect_entity_participant"||table.name==="architect_entity_tag"||table.name==="architect_entity_note"||table.name.startsWith("architect_stakeholder_")))for(const row of table.rows)if(row.values[1]===old)row.values[1]=next;for(const table of tables)table.rows.sort((a,b)=>a.rowid<b.rowid?-1:a.rowid>b.rowid?1:0);const oracle=Database.deserialize(await exportSqliteDatabase({tables}));try{expect(oracle.query("PRAGMA foreign_key_check").all()).toEqual([]);expect(await owner.programSnapshotFromSqliteDatabase(await importSqliteDatabase(oracle.serialize()))).toEqual(expected)}finally{oracle.close()}});


test("Architect actual row frontier precedes owned projection and reconstruction",async()=>{const{expected,database}=await completeOracleFixture(),count=database.tables.reduce((sum,table)=>sum+table.rows.length,0);await expect(owner.programSnapshotToSqliteDatabase(expected,{maxRows:count})).resolves.toEqual(database);await expect(owner.programSnapshotToSqliteDatabase(expected,{maxRows:count-1})).rejects.toThrow();await expect(owner.programSnapshotFromSqliteDatabase(database,{maxRows:count-1})).rejects.toThrow()});
test("Architect actual schema frontier agrees with independent SQLite text byte accounting",async()=>{const{expected,database,bytes}=await completeOracleFixture(),db=Database.deserialize(bytes);let size:number;try{size=(db.query("SELECT sum(length(CAST(name AS BLOB))+length(CAST(sql AS BLOB))) AS bytes FROM sqlite_schema WHERE type='table'").get() as{bytes:number}).bytes}finally{db.close()}for(const offset of laws.schemaLimitOffsets){const maximum=size+Number(offset[0]);if(offset[1])await expect(owner.programSnapshotToSqliteDatabase(expected,{maxSchemaBytes:maximum})).resolves.toEqual(database);else await expect(owner.programSnapshotToSqliteDatabase(expected,{maxSchemaBytes:maximum})).rejects.toThrow()}});
for(const phase of["projectSnapshot","reconstructSnapshot"] as const)test("Architect interior cancellation during "+phase,async()=>{const{expected,database}=await completeOracleFixture(),abort=new AbortController(),options={signal:abort.signal,onProgress:(event:{phase:string;completed:number})=>{if(event.phase===phase&&event.completed>0)abort.abort()}};if(phase==="projectSnapshot")await expect(owner.programSnapshotToSqliteDatabase(expected,options)).rejects.toThrow();else await expect(owner.programSnapshotFromSqliteDatabase(database,options)).rejects.toThrow()});

test("Architect every authored double position remains independently queryable with exact NaN words",async()=>{const{expected}=await completeOracleFixture(),input=structuredClone(expected),bits=0xfff0000000000123n;for(const[slot,field]of laws.binary64Fields)(input as unknown as Record<string,Record<string,unknown>[]>)[slot!]![0]![field!]={bits};const database=await owner.programSnapshotToSqliteDatabase(input),db=Database.deserialize(await exportSqliteDatabase(database));try{for(const[,field,table,column]of laws.binary64Fields){expect(db.query("SELECT "+column+" AS query,printf('%016llx',"+column+"_ieee754_bits) AS word,"+column+"_ieee754_class AS kind FROM "+table).get()).toEqual({query:null,word:"fff0000000000123",kind:"nan"})}expect(await owner.programSnapshotFromSqliteDatabase(await importSqliteDatabase(db.serialize()))).toEqual(input)}finally{db.close()}});

