fn sqlite_snapshot_architect_independent_sql_edits_reject_unowned_and_inconsistent_rows(){use store::ArtifactSqliteSnapshot;use store::sqlite_snapshot::*;let bytes=export_sqlite_database(&database(&complete_fixture()),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let corpus=laws();let input=serde_json::json!({"bytes":bytes,"sql":corpus["malformedSql"]});let script=r#"import{Database}from'bun:sqlite';const input=JSON.parse(await Bun.stdin.text());const results=[];for(const sql of input.sql){const db=Database.deserialize(new Uint8Array(input.bytes));db.run('PRAGMA ignore_check_constraints=ON');db.run(sql);results.push(Array.from(db.serialize()));db.close()}await Bun.write(Bun.stdout,JSON.stringify(results));"#;let edits:Vec<Vec<u8>>=serde_json::from_slice(&oracle(script,input.to_string().as_bytes())).unwrap();assert_eq!(edits.len(),corpus["malformedSql"].as_array().unwrap().len());for(sql,bytes)in corpus["malformedSql"].as_array().unwrap().iter().zip(edits){let actual=import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).and_then(|d|ProgramSnapshot::from_sqlite_database(&d,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())));assert!(actual.is_err(),"{sql}");}}
